const { assert } = require("chai");

const { decode, encode } = require("../lib");

describe("UTF", () => {
  it("should f-(f(x)) = x", () => {
    assert.equal(decode(encode("foo")), "foo");
    assert.equal(decode(encode("éé")), "éé");

    // TODO(sven): utf encoder fails here
    // assert.equal(decode(encode("见見")), "见見");
  });
});
